// ❌ OLD: An imperative multi-pass approach. It builds an
// intermediate Vec (evens), then another pass to transform, then sums
// — extra allocations and repeated iteration. It's also more verbose
// and easier to get wrong (indexing bugs, off-by-ones).
fn sum_evens(nums: &[i32]) -> i32 {
    let mut evens = Vec::new(); // ❌ OLD: intermediate heap allocation
    for &n in nums {
        if n % 2 == 0 {
            evens.push(n * 2);
        }
    }
    let mut total = 0;
    for n in &evens {
        total += n; // ❌ OLD: second pass over the temp
    }
    total
}

// ✅ NEW: The iterator pipeline is lazy, allocation-free, and fuses
// into a single pass. filter -> map -> sum compile into ONE loop with
// no intermediate Vec and no iterator object overhead (monomorphized
// + inlined).
fn sum_evens(nums: &[i32]) -> i32 {
    nums.iter()
        .filter(|n| n % 2 == 0) // ✅ NEW: keep evens
        .map(|n| n * 2) // ✅ NEW: transform
        .sum() // ✅ NEW: single fused pass, no intermediate storage
}

